INSERT INTO event VALUES(11,1,11,'context.blob',1,'["golden-host",1,"process-1"]',1767225611000,'{"payload":{"digest":"a1516829e616a7b5349733f50c8cc6c84856b87d1bb09660d73e5ab8b051b3a5","value":"{\"description\":\"Read and return workspace files. For text files you can supply an optional line range. PDFs (.pdf) and common image formats are returned as attachments so vision-capable models can inspect their pages or visual content.\",\"name\":\"read_file\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"path\":{\"description\":\"Workspace-relative or absolute file path to read.\",\"type\":\"string\"},\"range\":{\"anyOf\":[{\"additionalProperties\":false,\"properties\":{\"end\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Last line to read, inclusive and 1-indexed.\"},\"start\":{\"description\":\"First line to read, 1-indexed.\",\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"start\"],\"type\":\"object\"},{\"type\":\"null\"}],\"description\":\"Optional inclusive line range to read.\"}},\"required\":[\"path\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(12,1,12,'context.blob',1,'["golden-host",1,"process-1"]',1767225612000,'{"payload":{"digest":"2cf2ff971e6f13383c2471be46eea31fb47a6fc4a75d23fb4d7979933c98e440","value":"{\"description\":\"Manage the plan document and (optionally) the autonomous goal pursuing it.\\n\\nCommands:\\n- update: Propose or replace the plan. Required field: `objective` - a plain document stating what to achieve, the intended approach, and a verifiable stopping condition. Every update is presented to the user for approval; they may approve, run the plan as a goal, or reject. Update only when the objective or approach genuinely changes.\\n- pause: Self-pause the goal pursuing this plan when you genuinely need user input to proceed. Required field: `reason` describing what you need.\\n- complete: Mark the goal pursuing this plan complete. Required field: `reason` describing how you verified completion against current external state. Only call this once the objective''s stopping condition is verifiably true.\\n\\npause/complete only affect autonomous goals; with no goal running they return guidance for ordinary chat.\",\"name\":\"plan\",\"parameters\":{\"properties\":{\"command\":{\"enum\":[\"update\",\"pause\",\"complete\"],\"type\":\"string\"},\"objective\":{\"description\":\"The plan document: what to achieve, the intended approach, and a verifiable stopping condition. Plain prose or markdown - no structured steps.\",\"minLength\":1,\"type\":\"string\"},\"reason\":{\"description\":\"Why you are pausing: describe what you need from the user.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(13,1,13,'context.blob',1,'["golden-host",1,"process-1"]',1767225613000,'{"payload":{"digest":"472f9e2fe220981bdae35e8c6a033a90b2a2e8379191168c1908ca4778a16360","value":"{\"description\":\"Run a named agent as a child of this run: it works with its own tools on the prompt you give it.\\n\\nFrom a script, `agent(prompt, opts)` (the same as `tools.agent({ prompt, ...opts })`) waits for the child and resolves to its result: `{ response, files, structured?, runId, outcome, cost }`. It rejects with an Error named `AgentFailed`, `TimedOut`, or `Skipped` (the user stopped the child). With `background: true` it resolves to `{ runId }` at once and the result arrives as a follow-up. A completed call is reused, not run again, by a later call in this run with the same prompt, options and file contents; give two otherwise identical calls of one script distinct `id`s.\\n\\nCalled directly, the child runs in the background and its result arrives as a follow-up message; in a one-shot run the call waits for it.\\n\\nIt returns the agent''s final reply, or a `schema` value. Pick the agent whose description fits the task.\",\"name\":\"agent\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"agentName\":{\"description\":\"The agent to run. It works with its own tools.\",\"minLength\":1,\"type\":\"string\"},\"background\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"In a script: return `{ runId }` at once; the result arrives as a follow-up. A direct call always runs in the background, except in a one-shot run.\"},\"id\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Tells apart two otherwise identical calls: a completed call is reused by a later one with the same prompt, options and files.\"},\"label\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"A short title for the call’s card.\"},\"mediaFiles\":{\"anyOf\":[{\"items\":{\"type\":\"string\"},\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Images, figures, PDFs or audio attached to the prompt.\"},\"memories\":{\"anyOf\":[{\"items\":{\"type\":\"string\"},\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Memory file paths to attach (e.g. /memories/conventions.md). Content is injected into the agent prompt as read-only context. Use for project conventions, style guides, or accumulated knowledge the agent should follow.\"},\"model\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Model reference, `@effort` suffix allowed (`@low` … `@max`, `@none`). Defaults to your current model when available.\"},\"prompt\":{\"description\":\"The task, in plain prose. Name the files it concerns and copy every constraint the agent must follow: it does not see your conversation.\",\"minLength\":1,\"type\":\"string\"},\"schema\":{\"anyOf\":[{\"additionalProperties\":{},\"propertyNames\":{\"type\":\"string\"},\"type\":\"object\"},{\"type\":\"null\"}],\"description\":\"A JSON Schema object: the agent finishes by submitting a value of it, returned as `structured`.\"},\"timeoutMs\":{\"anyOf\":[{\"maximum\":86400000,\"minimum\":1000,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Stops the agent after this many milliseconds: `TimedOut`.\"},\"working_directory\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Absolute path for the subagent to operate in (e.g. a git worktree). All tool calls within the subagent will automatically use this as their root directory. Defaults to workspace root. Only accepted when git worktree support (`texra.git.worktreeSupport`) is enabled for this workspace.\"}},\"required\":[\"prompt\",\"agentName\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(14,1,14,'context.blob',1,'["golden-host",1,"process-1"]',1767225614000,'{"payload":{"digest":"9825ec75f204b6eb151e227537efc7071b999d481dc0c40295a700cc20b952a3","value":{"$b":"1a93a7b1b5489430338629d236e9b79c1141d9936c727da8e32f05e0d5301949"}}}');
INSERT INTO event VALUES(15,1,15,'context.blob',1,'["golden-host",1,"process-1"]',1767225615000,'{"payload":{"digest":"31e3e423b765cd10ac7574bb81a80053dea4120081a2a7b8c05bf8e2fa998020","value":"{\"description\":\"Manage persistent memory files under /memories (view, create, str_replace, insert, delete, rename, pin, unpin).\\n\\n`view` with no path defaults to the /memories root listing; `rename` uses old_path/new_path instead of path; all other commands require path.\\nDirectory listings are paginated: use offset/limit to page through results (default: offset 0, limit 100).\\n\\nUse `pin` to mark a memory as a core long-term insight (techniques, strategies, pitfalls, best practices). Pinned memories are always loaded at session start. Use `unpin` to remove the pinned status. Maximum 10 pinned memories allowed.\",\"name\":\"memory\",\"parameters\":{\"properties\":{\"command\":{\"enum\":[\"view\",\"create\",\"str_replace\",\"insert\",\"delete\",\"rename\",\"pin\",\"unpin\"],\"type\":\"string\"},\"file_text\":{\"type\":\"string\"},\"insert_line\":{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},\"insert_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Text to insert. Aliased by `new_str` if omitted.\"},\"limit\":{\"anyOf\":[{\"maximum\":200,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Max entries to return from directory listing. Default: 100, max: 200.\"},\"new_path\":{\"description\":\"Path under /memories (e.g. /memories/notes.md).\",\"type\":\"string\"},\"new_str\":{\"type\":\"string\"},\"offset\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Zero-based offset into the directory listing. Use with limit for pagination. Default: 0.\"},\"old_path\":{\"description\":\"Path under /memories (e.g. /memories/notes.md).\",\"type\":\"string\"},\"old_str\":{\"type\":\"string\"},\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Path under /memories (e.g. /memories/notes.md). Defaults to the /memories root directory listing when omitted.\"},\"view_range\":{\"anyOf\":[{\"items\":{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},\"maxItems\":2,\"minItems\":2,\"type\":\"array\"},{\"type\":\"null\"}]}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
