INSERT INTO event VALUES(175,4,10,'context.blob',1,'["golden-host",3,"process-3"]',1767225775000,'{"payload":{"digest":"93fed875a9a5f637ed6302e5a9a1e2b56133f82c9efbb0d65a360c0b1873cd8f","value":"{\"sections\":{\"memory-workflow plugin\":\"<memory_tool_instructions>\\nPinned memories are always loaded unless the user forbids memory use. At session start, `view` the `/memories` directory to find entries marked [pinned]. If the listing is truncated, continue until you have seen every [pinned] entry. Then `view` each pinned file so its content applies, regardless of how self-contained the request looks. Pinned entries are the core reusable insights (techniques, strategies, pitfalls) accumulated across sessions. The directory listing alone does not load their content. Beyond pinned entries, use memory when the request may depend on prior sessions, durable user preferences, or shared agent context. For a self-contained request, do not read unpinned memory files or write memory merely because the tool is available. Listing the directory is still appropriate because it is needed to find pinned entries.\\n\\nYour memory persists across conversations. When memory is in play, record durable progress, decisions, and user preferences (writing style, conventions, formatting, workflow). Keep the folder current and organized by updating, renaming, or deleting files rather than duplicating them. Do not store what the workspace files already state. When project context, coding patterns, or conventions are relevant to the task and git is available, look into git history (commit messages, PR descriptions, recent changes) to understand them. Use `pin` only for long-term reusable insights, never task-specific progress notes. Use `unpin` for entries that no longer earn their place.\\n</memory_tool_instructions>\",\"tool-call\":\"When using a tool, follow the JSON schema exactly and include all required properties.\\nAlways produce valid JSON when calling a tool.\\nDo not call tools that are not provided or any multi_tool_use variants.\\nCall tools sequentially and wait for the output before calling another.\"},\"tools\":[\"read_file\",\"glob\",\"grep\",\"extract_figures\",\"extract_bib_entries\",\"extract_tikz_figures\",\"arxiv_search\",\"memory\"]}"}}');
INSERT INTO event VALUES(176,4,11,'context.blob',1,'["golden-host",3,"process-3"]',1767225776000,'{"payload":{"digest":"a1516829e616a7b5349733f50c8cc6c84856b87d1bb09660d73e5ab8b051b3a5","value":"{\"description\":\"Read and return workspace files. For text files you can supply an optional line range. PDFs (.pdf) and common image formats are returned as attachments so vision-capable models can inspect their pages or visual content.\",\"name\":\"read_file\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"path\":{\"description\":\"Workspace-relative or absolute file path to read.\",\"type\":\"string\"},\"range\":{\"anyOf\":[{\"additionalProperties\":false,\"properties\":{\"end\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Last line to read, inclusive and 1-indexed.\"},\"start\":{\"description\":\"First line to read, 1-indexed.\",\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"}},\"required\":[\"start\"],\"type\":\"object\"},{\"type\":\"null\"}],\"description\":\"Optional inclusive line range to read.\"}},\"required\":[\"path\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(177,4,12,'context.blob',1,'["golden-host",3,"process-3"]',1767225777000,'{"payload":{"digest":"bfbfe43412bcfbfa973dc9c3313b5797052b8c214dcc850077775d3e617c881c","value":"{\"description\":\"Find files matching glob patterns (e.g., \\\"**/*.tex\\\", \\\"src/**/*.ts\\\"). Returns paths sorted by modification time.\",\"name\":\"glob\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Directory to search within. Defaults to the workspace root.\"},\"pattern\":{\"description\":\"Glob pattern to match, such as \\\"**/*.tex\\\" or \\\"src/**/*.ts\\\".\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"pattern\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(178,4,13,'context.blob',1,'["golden-host",3,"process-3"]',1767225778000,'{"payload":{"digest":"ac4a7dbc9c522a314b37f12f68ce53277a02649aaf582e7af35bc2d03a5d6a9c","value":"{\"description\":\"Search file contents using regex patterns. For surrounding lines use -C with output_mode \\\"content\\\".\",\"name\":\"grep\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"-A\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Lines of context AFTER each match (only with output_mode \\\"content\\\").\"},\"-B\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Lines of context BEFORE each match (only with output_mode \\\"content\\\").\"},\"-C\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Lines of context before AND after each match.\"},\"-i\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Case-insensitive search.\"},\"-n\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Show line numbers.\"},\"glob\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Glob filter for file names (e.g. \\\"*.tex\\\").\"},\"head_limit\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Limit to first N results.\"},\"literal\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Exact string, not regex.\"},\"multiline\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Enable multiline matching (pattern can span lines).\"},\"offset\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Skip first N results.\"},\"output_mode\":{\"anyOf\":[{\"enum\":[\"content\",\"files_with_matches\",\"count\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Must be \\\"content\\\", \\\"files_with_matches\\\", or \\\"count\\\". For context lines around matches, use -C instead.\"},\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"File or directory to search in.\"},\"pattern\":{\"description\":\"Regex pattern.\",\"minLength\":1,\"type\":\"string\"},\"type\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Ripgrep file type filter (e.g. \\\"tex\\\", \\\"py\\\").\"}},\"required\":[\"pattern\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(179,4,14,'context.blob',1,'["golden-host",3,"process-3"]',1767225779000,'{"payload":{"digest":"17106c542dfe272bc7367851fd9238667cdfdad61de8f39a3d0fb4c1bac64da6","value":"{\"description\":\"Resolve and list figure assets referenced by a LaTeX document, returning attachments when available.\",\"name\":\"extract_figures\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"texPath\":{\"description\":\"Path to the primary LaTeX file to inspect.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"texPath\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(180,4,15,'context.blob',1,'["golden-host",3,"process-3"]',1767225780000,'{"payload":{"digest":"20c742f1752c52d3dc53be8e335f791b7daac2578e3e2afbd1901086058d1079","value":"{\"description\":\"Collect BibTeX records for citations referenced in a LaTeX document.\",\"name\":\"extract_bib_entries\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"bibPath\":{\"anyOf\":[{\"description\":\"Optional path to a BibTeX file to include when resolving citations.\",\"minLength\":1,\"type\":\"string\"},{\"type\":\"null\"}]},\"texPath\":{\"description\":\"Path to the LaTeX file to scan for citations.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"texPath\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(181,4,16,'context.blob',1,'["golden-host",3,"process-3"]',1767225781000,'{"payload":{"digest":"e2b4cf740e0175b4d91dc89340fdc7ad98b01c199d0b7cdccaf609ff8173f367","value":"{\"description\":\"Discover TikZ figures inside a LaTeX document and optionally compile them into standalone PDFs.\",\"name\":\"extract_tikz_figures\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"compile\":{\"anyOf\":[{\"description\":\"Compile extracted TikZ pictures into standalone PDFs.\",\"type\":\"boolean\"},{\"type\":\"null\"}]},\"texPath\":{\"description\":\"Path to the LaTeX file containing TikZ figures.\",\"minLength\":1,\"type\":\"string\"}},\"required\":[\"texPath\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(182,4,17,'context.blob',1,'["golden-host",3,"process-3"]',1767225782000,'{"payload":{"digest":"f2aebb4f8d6e5f7d3e22ca87af6a0cc3e71f783fce6f31a6f0d326f418c03b9c","value":"{\"description\":\"Search arXiv for papers and return basic metadata for each hit. Use field=\\\"author\\\" for author name searches.\",\"name\":\"arxiv_search\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"categories\":{\"anyOf\":[{\"items\":{\"type\":\"string\"},\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Optional arXiv category filters such as \\\"math.NT\\\" or \\\"cs.AI\\\".\"},\"field\":{\"anyOf\":[{\"enum\":[\"all\",\"author\",\"title\",\"abstract\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Search field: \\\"author\\\" for author names, \\\"title\\\" for paper titles, \\\"abstract\\\" for abstracts, \\\"all\\\" (default) for all fields\"},\"maxResults\":{\"anyOf\":[{\"exclusiveMinimum\":0,\"maximum\":50,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Maximum number of papers to return.\"},\"query\":{\"description\":\"Search query terms, title text, or author names.\",\"type\":\"string\"},\"sortBy\":{\"anyOf\":[{\"enum\":[\"relevance\",\"lastUpdatedDate\",\"submittedDate\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"arXiv sort field to use.\"},\"sortOrder\":{\"anyOf\":[{\"enum\":[\"ascending\",\"descending\"],\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Sort direction for results.\"},\"start\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Zero-based result offset for pagination.\"}},\"required\":[\"query\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(183,4,18,'context.blob',1,'["golden-host",3,"process-3"]',1767225783000,'{"payload":{"digest":"31e3e423b765cd10ac7574bb81a80053dea4120081a2a7b8c05bf8e2fa998020","value":"{\"description\":\"Manage persistent memory files under /memories (view, create, str_replace, insert, delete, rename, pin, unpin).\\n\\n`view` with no path defaults to the /memories root listing; `rename` uses old_path/new_path instead of path; all other commands require path.\\nDirectory listings are paginated: use offset/limit to page through results (default: offset 0, limit 100).\\n\\nUse `pin` to mark a memory as a core long-term insight (techniques, strategies, pitfalls, best practices). Pinned memories are always loaded at session start. Use `unpin` to remove the pinned status. Maximum 10 pinned memories allowed.\",\"name\":\"memory\",\"parameters\":{\"properties\":{\"command\":{\"enum\":[\"view\",\"create\",\"str_replace\",\"insert\",\"delete\",\"rename\",\"pin\",\"unpin\"],\"type\":\"string\"},\"file_text\":{\"type\":\"string\"},\"insert_line\":{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},\"insert_text\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Text to insert. Aliased by `new_str` if omitted.\"},\"limit\":{\"anyOf\":[{\"maximum\":200,\"minimum\":1,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Max entries to return from directory listing. Default: 100, max: 200.\"},\"new_path\":{\"description\":\"Path under /memories (e.g. /memories/notes.md).\",\"type\":\"string\"},\"new_str\":{\"type\":\"string\"},\"offset\":{\"anyOf\":[{\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Zero-based offset into the directory listing. Use with limit for pagination. Default: 0.\"},\"old_path\":{\"description\":\"Path under /memories (e.g. /memories/notes.md).\",\"type\":\"string\"},\"old_str\":{\"type\":\"string\"},\"path\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Path under /memories (e.g. /memories/notes.md). Defaults to the /memories root directory listing when omitted.\"},\"view_range\":{\"anyOf\":[{\"items\":{\"maximum\":9007199254740991,\"minimum\":1,\"type\":\"integer\"},\"maxItems\":2,\"minItems\":2,\"type\":\"array\"},{\"type\":\"null\"}]}},\"required\":[\"command\"],\"type\":\"object\"}}"}}');
