INSERT INTO event VALUES(215,5,11,'context.blob',1,'["golden-host",4,"process-4"]',1767225815000,'{"payload":{"digest":"472f9e2fe220981bdae35e8c6a033a90b2a2e8379191168c1908ca4778a16360","value":"{\"description\":\"Run a named agent as a child of this run: it works with its own tools on the prompt you give it.\\n\\nFrom a script, `agent(prompt, opts)` (the same as `tools.agent({ prompt, ...opts })`) waits for the child and resolves to its result: `{ response, files, structured?, runId, outcome, cost }`. It rejects with an Error named `AgentFailed`, `TimedOut`, or `Skipped` (the user stopped the child). With `background: true` it resolves to `{ runId }` at once and the result arrives as a follow-up. A completed call is reused, not run again, by a later call in this run with the same prompt, options and file contents; give two otherwise identical calls of one script distinct `id`s.\\n\\nCalled directly, the child runs in the background and its result arrives as a follow-up message; in a one-shot run the call waits for it.\\n\\nIt returns the agent''s final reply, or a `schema` value. Pick the agent whose description fits the task.\",\"name\":\"agent\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"agentName\":{\"description\":\"The agent to run. It works with its own tools.\",\"minLength\":1,\"type\":\"string\"},\"background\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"In a script: return `{ runId }` at once; the result arrives as a follow-up. A direct call always runs in the background, except in a one-shot run.\"},\"id\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Tells apart two otherwise identical calls: a completed call is reused by a later one with the same prompt, options and files.\"},\"label\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"A short title for the call’s card.\"},\"mediaFiles\":{\"anyOf\":[{\"items\":{\"type\":\"string\"},\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Images, figures, PDFs or audio attached to the prompt.\"},\"memories\":{\"anyOf\":[{\"items\":{\"type\":\"string\"},\"type\":\"array\"},{\"type\":\"null\"}],\"description\":\"Memory file paths to attach (e.g. /memories/conventions.md). Content is injected into the agent prompt as read-only context. Use for project conventions, style guides, or accumulated knowledge the agent should follow.\"},\"model\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Model reference, `@effort` suffix allowed (`@low` … `@max`, `@none`). Defaults to your current model when available.\"},\"prompt\":{\"description\":\"The task, in plain prose. Name the files it concerns and copy every constraint the agent must follow: it does not see your conversation.\",\"minLength\":1,\"type\":\"string\"},\"schema\":{\"anyOf\":[{\"additionalProperties\":{},\"propertyNames\":{\"type\":\"string\"},\"type\":\"object\"},{\"type\":\"null\"}],\"description\":\"A JSON Schema object: the agent finishes by submitting a value of it, returned as `structured`.\"},\"timeoutMs\":{\"anyOf\":[{\"maximum\":86400000,\"minimum\":1000,\"type\":\"integer\"},{\"type\":\"null\"}],\"description\":\"Stops the agent after this many milliseconds: `TimedOut`.\"},\"working_directory\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"Absolute path for the subagent to operate in (e.g. a git worktree). All tool calls within the subagent will automatically use this as their root directory. Defaults to workspace root. Only accepted when git worktree support (`texra.git.worktreeSupport`) is enabled for this workspace.\"}},\"required\":[\"prompt\",\"agentName\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(216,5,12,'context.blob',1,'["golden-host",4,"process-4"]',1767225816000,'{"payload":{"digest":"7ade54e9f3ef563a7529380af8cdcdfa326ef09e9909a63ad61cf258aad51021","value":"{\"description\":\"A document task''s revision prompt: the task''s documents, every earlier request with the reply it got, and this revision''s request with the compile failures that rejected the last one and the `critique` of it, if any. Resolves to `{ prompt, mediaFiles, memories, revisions, reflect }`: `memories` are the launch''s, for the revision''s agent; `reflect` says the task reviews each revision but the last (`document_review`).\",\"name\":\"document_context\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"critique\":{\"anyOf\":[{\"type\":\"string\"},{\"type\":\"null\"}],\"description\":\"The critic''s review of the last revision.\"},\"revision\":{\"description\":\"The revision, from 0, in the order the task runs them.\",\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"revision\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(217,5,13,'context.blob',1,'["golden-host",4,"process-4"]',1767225817000,'{"payload":{"digest":"0043066db6bff1ab41e86db7fb999f1207d7ee5c07e097ba5a3e82a89963d920","value":"{\"description\":\"Take the documents out of the reply a revision''s agent run gave (`run`, the run id `agent()` resolved with): they become the revision''s output files, with their lineage and diff stats. Resolves to `{ files, missing }`.\",\"name\":\"document_extract\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"revision\":{\"description\":\"The revision, from 0, in the order the task runs them.\",\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"},\"run\":{\"description\":\"The revision''s agent run.\",\"minLength\":6,\"pattern\":\"^[0-9a-f][-0-9a-f]*$\",\"type\":\"string\"}},\"required\":[\"revision\",\"run\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(218,5,14,'context.blob',1,'["golden-host",4,"process-4"]',1767225818000,'{"payload":{"digest":"fa20993432b493015011b4cc4d730d1f0d3465f2d0678f9352a172ce3d83333e","value":"{\"description\":\"Compile a revision''s .tex outputs. Resolves to `{ failures, checked }`: the outputs that failed with their logs, and whether a check ran at all (auto-compile off, or no LaTeX toolchain, runs none).\",\"name\":\"document_compile\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"revision\":{\"description\":\"The revision, from 0, in the order the task runs them.\",\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"revision\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(219,5,15,'context.blob',1,'["golden-host",4,"process-4"]',1767225819000,'{"payload":{"digest":"0dc27e833f4805d220415b9d5afce5a9fd33d7a4eb049d9737b5d8fbf4bdce89","value":"{\"description\":\"Run latexdiff of a revision''s outputs against the documents the task started from. Resolves to `{ diffs }`, the diff files it wrote.\",\"name\":\"document_diff\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"revision\":{\"description\":\"The revision, from 0, in the order the task runs them.\",\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"revision\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(220,5,16,'context.blob',1,'["golden-host",4,"process-4"]',1767225820000,'{"payload":{"digest":"82bc6791175bc835b86dabbfc53d2c8ae0e41ef3f6adb01f888ceff50459275b","value":"{\"description\":\"The evidence a critic reviews for a revision: the user''s instruction, the task''s requests so far, the diff of each output against the document it started from, and the compile result. Resolves to `{ prompt }`, to pass to the `critic` agent.\",\"name\":\"document_review\",\"parameters\":{\"additionalProperties\":false,\"properties\":{\"checked\":{\"anyOf\":[{\"type\":\"boolean\"},{\"type\":\"null\"}],\"description\":\"Whether the revision''s compile check ran (`document_compile`).\"},\"revision\":{\"description\":\"The revision, from 0, in the order the task runs them.\",\"maximum\":9007199254740991,\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"revision\"],\"type\":\"object\"}}"}}');
INSERT INTO event VALUES(221,5,17,'context.blob',1,'["golden-host",4,"process-4"]',1767225821000,'{"payload":{"digest":"2868f078af78ea8b802a0b15b8b896e5382f64f33d2a7d53865c533f2c27cf68","value":"{\"description\":\"End the document task: propose the outputs of its latest revision that wrote any for the user to accept. Fails, naming the failed outputs, when that revision did not compile and failed compiles are rejected. Resolves to `{ files, documents }`: the proposed files and every revision''s documents, which the task''s run ends with.\",\"name\":\"document_propose\",\"parameters\":{\"additionalProperties\":false,\"properties\":{},\"type\":\"object\"}}"}}');
