INSERT INTO event VALUES(397,8,2,'run.config',1,'["golden-host",5,"process-5"]',1767225997000,'{"config":{"inputFiles":[],"contextFiles":[],"mediaFiles":[],"outputFiles":[],"editedFile":null,"agent":"golden_chat","agentSource":"custom","model":"openai/gpt-5.6-sol@medium","instruction":"Start the golden chat.","toolConfig":{"autoExtractFigure":false,"autoExtractTikzFigure":false,"attachTeXCount":false,"autoCompileInputPdf":false,"reflect":false},"memories":[],"workingDirectory":"/golden/project"}}');
